package main

import "github.com/corentings/chess/v2"

// Jointly calibrated on opening-family-separated data; see the frozen model
// and held-out results in tools/benchmark/research/v0.18-evaluation-model.
var modelMiddle = [chess.EvalFeatureCount]int{0, 8, 6, 0, 13, 4, 14, 2, 0, 1, 0, 7}
var modelEnding = [chess.EvalFeatureCount]int{0, 8, 6, 0, 0, 0, 0, 0, 4, 0, 0, 4}

func modelAdjustment(position *chess.Position, perspective chess.Color) int {
	f := position.Board().EvaluationFeatures()
	middle, ending := 0, 0
	for i, value := range f.Values {
		middle += int(value) * modelMiddle[i]
		ending += int(value) * modelEnding[i]
	}
	delta := (middle*f.Phase + ending*(24-f.Phase)) / 24
	if perspective == chess.Black {
		return -delta
	}
	return delta
}

