package main

import (
	"encoding/json"
	"github.com/corentings/chess/v2"
	"os"
	"testing"
)

var evaluationCostSink int

func BenchmarkEvaluationModelCost(b *testing.B) {
	data, err := os.ReadFile("tools/benchmark/research/v0.17-search-moves/inputs.json")
	if err != nil {
		b.Fatal(err)
	}
	var inputs struct{ Cases []struct{ FEN string } }
	if err = json.Unmarshal(data, &inputs); err != nil {
		b.Fatal(err)
	}
	positions := make([]*chess.Position, len(inputs.Cases))
	for i, c := range inputs.Cases {
		option, e := chess.FEN(c.FEN)
		if e != nil {
			b.Fatal(e)
		}
		positions[i] = chess.NewGame(option).Position()
	}
	for _, name := range []string{"baseline", "features", "combined-cost-only", "fitted-model"} {
		b.Run(name, func(b *testing.B) {
			b.ReportAllocs()
			sum := 0
			for i := 0; i < b.N; i++ {
				p := positions[i%len(positions)]
				if name == "fitted-model" {
					sum += staticScore(p, chess.White)
					continue
				}
				if name != "features" {
					sum += baseStaticScore(p, chess.White)
				}
				if name != "baseline" {
					f := p.Board().EvaluationFeatures()
					for j, v := range f.Values {
						sum += (int(v)*(j+1)*f.Phase + int(v)*(12-j)*(24-f.Phase)) / 24
					}
				}
			}
			evaluationCostSink = sum
		})
	}
}

func TestEvaluationFeatureGeometry(t *testing.T) {
	p := chess.StartingPosition()
	f := p.Board().EvaluationFeatures()
	if f.Phase != 24 {
		t.Fatal("starting phase", f.Phase)
	}
	for _, v := range f.Values {
		if v != 0 {
			t.Fatal("symmetric start is asymmetric", f)
		}
	}
	// A passed pawn's progress must increase as it advances, but an enemy pawn
	// ahead on an adjacent file removes the passed status.
	score := func(fen string) chess.EvalFeatures { return evalFEN(t, fen).Board().EvaluationFeatures() }
	a := score("7k/8/8/8/P7/8/8/K7 w - - 0 1")
	advance := score("7k/8/P7/8/8/8/8/K7 w - - 0 1")
	blocked := score("7k/1p6/P7/8/8/8/8/K7 w - - 0 1")
	if advance.Values[7] <= a.Values[7] || blocked.Values[7] != 0 {
		t.Fatal("passed pawn controls", a, advance, blocked)
	}
	shelter := score("4k3/ppp5/8/8/8/8/5PPP/6K1 w - - 0 1")
	if shelter.Values[6] != 3 {
		t.Fatal("asymmetric pawn shelter mask", shelter)
	}
	// Blocked own mobility is distinguished from an open board without requiring
	// a fixed chess move or a reference engine's unique preferred line.
	open := score("7k/8/8/8/3N4/8/8/K7 w - - 0 1")
	trapped := score("7k/8/2P1P3/1P3P2/3N4/1P3P2/2P1P3/K7 w - - 0 1")
	if open.Values[0] <= trapped.Values[0] {
		t.Fatal("mobility control", open, trapped)
	}
	if got := testing.AllocsPerRun(1000, func() { evaluationCostSink = int(p.Board().EvaluationFeatures().Values[0]) }); got != 0 {
		t.Fatal("feature allocation", got)
	}
}

func TestFrozenModelScalarAndPerspective(t *testing.T) {
	data, err := os.ReadFile("tools/benchmark/research/v0.18-evaluation-model/scalar-expectations.json")
	if err != nil {
		t.Fatal(err)
	}
	var input struct {
		Cases []struct {
			ID, FEN  string
			Expected int
		}
	}
	if err = json.Unmarshal(data, &input); err != nil {
		t.Fatal(err)
	}
	for _, c := range input.Cases {
		p := evalFEN(t, c.FEN)
		if staticScore(p, chess.White) != c.Expected || staticScore(p, chess.Black) != -c.Expected {
			t.Fatalf("scalar/perspective %s", c.ID)
		}
	}
	for pt, want := range map[chess.PieceType]int{chess.Pawn: 100, chess.Knight: 300, chess.Bishop: 300, chess.Rook: 500, chess.Queen: 900} {
		if pieceValues[pt] != want {
			t.Fatal("material changed")
		}
	}
}

