			}
			before := game.FEN()
			if got := bestMove(game, strings.Fields("searchmoves "+tt.moves)); got != tt.want {
				t.Fatalf("move = %q, want %q", got, tt.want)
			}
			if game.FEN() != before || len(game.Moves()) != 0 {
