func TestSearchFindsBestCapture(t *testing.T) {
	game, err := parsePosition(strings.Fields("fen r6k/7P/8/8/8/8/Q7/7K b - - 0 1"))
	if err != nil {
		t.Fatal(err)
	}
	// Taking our queen leaves our pawn (1) against their rook (5).
	// Taking only the pawn would leave a much better material balance for us.
	p := game.Position()
	best, score, complete := (&searcher{}).root(p, rootMoves(p, nil), 1)
	if !complete || len(best) != 1 || best[0] != "a8a2" || score != -exhaustiveScore(p, 1) {
		t.Fatalf("queen capture: best %v score %d complete %v", best, score, complete)
	}
	for _, move := range p.ValidMoves() {
		if move.String() == "a8a2" && materialScore(p.Update(&move), chess.Black) != 400 {
			t.Fatal("capture changed the material units")
		}
	}
}

